      size: size, anchor: 'middle', style: italic ? 'italic' : 'normal'
    });
  }

  var gfx = {};
  EDGES.forEach(function (e) {
    var p1 = V[e.u], p2 = V[e.v];
    var band = gBand.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: '#a2a2a2', width: 16, linecap: 'round' }).opacity(0);
    var line = gLine.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: '#111', width: 3.4, linecap: 'round' });
    var hl = gHL.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: ACCENT, width: 6, linecap: 'round' }).opacity(0);
    var lbl = halo(serifText(gLabel, String(e.w), 36, false));
    lbl.center(e.lx, e.ly);
    var hit = gHit.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: '#fff', width: 26, opacity: 0 })
      .attr('pointer-events', 'stroke').css('cursor', 'pointer');

    var name = e.u + '\u2013' + e.v;
    function statusWord() {
      var inT = treeSet().indexOf(e.id) >= 0;
      var added = treeSet().slice(0, buildCount).indexOf(e.id) >= 0;
      if (added) return 'in the tree';
      if (inT) return 'in the tree (not added yet)';
      return 'not in the tree';
    }
    hit.on('mousemove', function (ev) {
      showTooltip(name + ', weight ' + e.w + ' — ' + statusWord(), ev);
    }).on('mouseleave', hideTooltip)
      .on('click', function () {
        selected = e.id;
        render();
        var inT = treeSet().indexOf(e.id) >= 0;
        showPopup('Edge ' + name + ' (weight ' + e.w + ')',
          inT
            ? 'This edge belongs to the current minimum spanning tree. Deleting it would break the tree into two components, and every other edge that could reconnect them costs at least ' + e.w + '. The whole tree weighs 37.'
            : 'This edge is left out. Adding it to the 8 tree edges would close a cycle, and every edge already on that cycle is no heavier than ' + e.w + ', so swapping it in could only raise the total above 37.');
      });

    gfx[e.id] = { band: band, line: line, hl: hl, lbl: lbl, hit: hit };
  });

  var rings = {}, nodeCircles = {};
  NODES.forEach(function (n) {
    var p = V[n];
    rings[n] = gRing.circle(2 * (R + 7)).center(p[0], p[1])
      .fill('none').stroke({ color: ACCENT, width: 5 }).opacity(0);
    gShadow.circle(2 * R).center(p[0] + 5, p[1] + 6).fill('#b8b8b8').opacity(0.55);
    var c = gNode.circle(2 * R).center(p[0], p[1])
      .fill('#d9d9d9').stroke({ color: '#222', width: 3 }).css('cursor', 'pointer');
    var t = serifText(gLabel, n, 40, true).fill('#000');
    t.center(p[0], p[1] - 2);
    c.on('mousemove', function (ev) { showTooltip('vertex ' + n, ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Vertex ' + n,
          'A spanning tree must touch every one of the nine vertices. With 9 vertices, exactly 9 − 1 = 8 edges are needed: fewer leaves a vertex unreached, more would create a cycle.');
      });
    nodeCircles[n] = c;
  });

  // ── readout / legend strip ────────────────────────────────────────────
  gPanel.line(20, 522, 1180, 522).stroke({ color: '#e2e2e2', width: 2 });
  gPanel.line(20, 553, 72, 553).stroke({ color: '#a2a2a2', width: 14, linecap: 'round' });
  gPanel.line(20, 553, 72, 553).stroke({ color: '#111', width: 3, linecap: 'round' });
  gPanel.line(215, 553, 267, 553).stroke({ color: '#111', width: 3, linecap: 'round' });

  function panelText(str, x) {
    var t = gPanel.text(str).font({ family: 'Helvetica, Arial, sans-serif', size: 19, anchor: 'start' }).fill('#444');
    t.x(x); t.cy(553);
    return t;
  }
  panelText('tree edge', 82);
  panelText('excluded edge', 277);
  var pTotal = panelText('Tree weight: 37   (8 of 8 edges)', 500);
  pTotal.fill('#111');
  var pSel = panelText('Selected: — (click an edge)', 840);

  // ── render ────────────────────────────────────────────────────────────
  function selLabel(id) {
    var e = byId[id];
    var inT = treeSet().indexOf(id) >= 0;
    var added = treeSet().slice(0, buildCount).indexOf(id) >= 0;
    var st = added ? 'in tree' : (inT ? 'in tree, not added yet' : 'not in tree');
    return 'Selected: ' + e.u + '\u2013' + e.v + ' (' + e.w + ') — ' + st;
  }

  function render() {
    var added = treeSet().slice(0, buildCount);
    var total = 0;
    EDGES.forEach(function (e) {
      var on = added.indexOf(e.id) >= 0;
      if (on) total += e.w;
      gfx[e.id].band.opacity(on ? 1 : 0);
      var sel = (selected === e.id);
      gfx[e.id].hl.opacity(sel ? 1 : 0);
      gfx[e.id].lbl.fill(sel ? ACCENT : '#000');
    });
    var reached = {};
    added.forEach(function (id) { reached[byId[id].u] = 1; reached[byId[id].v] = 1; });
    var showRings = (buildCount > 0 && buildCount < 8);
    NODES.forEach(function (n) { rings[n].opacity(showRings && reached[n] ? 1 : 0); });

    pTotal.text('Tree weight: ' + total + '   (' + buildCount + ' of 8 edges)');
    pSel.text(selected ? selLabel(selected) : 'Selected: — (click an edge)');

    var bs = document.getElementById('buildStatus');
    if (bs) bs.textContent = buildCount + ' of 8 edges added · weight ' + total +
      (buildCount === 8 ? ' (spanning)' : '');
    var bt = document.getElementById('buildTreeInput');
    if (bt) bt.disabled = (buildCount === 8);
    var si = document.getElementById('selInfo');
    if (si) {
      if (selected) {
        var e = byId[selected];
        var inT = treeSet().indexOf(selected) >= 0;
        si.textContent = e.u + '\u2013' + e.v + ', weight ' + e.w + ' — ' +
          (inT ? 'part of this minimum spanning tree.' : 'excluded: it would close a cycle of lighter edges.');
      } else {
        si.textContent = 'Click any edge in the figure to inspect its weight and status.';
      }
    }
  }

  // ── controls ──────────────────────────────────────────────────────────
  window.toggle_treeVariant = function (on) {
    variant = on ? 'B' : 'A';
    render();
  };
  window.trigger_buildTree = function () {
    if (buildCount < 8) { buildCount++; render(); }
  };
  window.trigger_resetBuild = function () {
    buildCount = 0; selected = null; render();
  };

  // ── demo steps ────────────────────────────────────────────────────────
  var STEPS = [
    { title: 'The wiring problem', narration: 'Nine pins must be connected; every possible interconnection is an edge and its weight is the length of wire it would need. All fourteen candidate connections are shown, none chosen yet.', count: 0, variant: 'A', sel: null },
    { title: 'Cheapest links first', narration: 'Adding edges one at a time, the light connections h–g (1), g–f (2) and c–i (2) appear. Watch the orange reached-vertex markers spread outward — the set stays acyclic the whole time.', count: 3, variant: 'A', sel: null },
    { title: 'Spanning every vertex', narration: 'By the eighth edge all nine vertices are reached with exactly 8 = 9 − 1 edges and no cycle. The running total is 37 — the minimum possible wire length.', count: 8, variant: 'A', sel: null },
    { title: 'Compare the edges left out', narration: 'Click the heavy unshaded edges such as d–f (14, highlighted) and b–h (11): each would close a cycle and cost more than an edge already in the tree, so it is excluded.', count: 8, variant: 'A', sel: 'd-f' },
    { title: 'A minimum spanning tree is not unique', narration: 'Swap b–c (8) for a–h (8): the gray band shifts, the tree still spans all nine vertices with no cycle, and the total weight is still 37.', count: 8, variant: 'B', sel: null }
  ];
  var stepIndex = 2; // default view == the original figure (full Tree A)

  function applyStep(i) {
    stepIndex = Math.max(0, Math.min(STEPS.length - 1, i));
    var s = STEPS[stepIndex];
    buildCount = s.count;
    variant = s.variant;
    selected = s.sel;
    var cb = document.getElementById('treeVariantInput');
    if (cb) cb.checked = (variant === 'B');
    var n = document.getElementById('demoNarration');
    if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (stepIndex + 1) + ' / ' + STEPS.length;
    render();
  }
  window.nextStep = function () { applyStep(stepIndex + 1); };
  window.prevStep = function () { applyStep(stepIndex - 1); };

  applyStep(2);
  window.__markRendered();
})();
// @FIGURE_CODE_END

