    var band = gBand.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: '#9c9c9c', width: BAND_W, linecap: 'butt' }).opacity(0);

    var line = gLine.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: '#111', width: LINE_W, linecap: 'round' });

    var rA = offsetLine(p1, p2, RULE_OFF), rB = offsetLine(p1, p2, -RULE_OFF);
    var ruleA = gLine.line(rA[0], rA[1], rA[2], rA[3])
      .stroke({ color: '#111', width: RULE_W, linecap: 'butt' }).opacity(0);
    var ruleB = gLine.line(rB[0], rB[1], rB[2], rB[3])
      .stroke({ color: '#111', width: RULE_W, linecap: 'butt' }).opacity(0);

    var hl = gHL.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: ACCENT, width: 7, linecap: 'round' }).opacity(0);

    var lbl = halo(serifText(gLabel, String(e.w), 44, false));
    lbl.center(e.lx, e.ly);

    var hit = gHit.line(p1[0], p1[1], p2[0], p2[1])
      .stroke({ color: '#fff', width: 30, opacity: 0 })
      .attr('pointer-events', 'stroke').css('cursor', 'pointer');

    var name = e.u + '\u2013' + e.v;
    function statusWord() {
