  var rings = {};
  NODES.forEach(function (n) {
    var p = V[n];
    rings[n] = gRing.circle(2 * (R + 8)).center(p[0], p[1])
      .fill('none').stroke({ color: ACCENT, width: 6 }).opacity(0);
    gShadow.circle(2 * R).center(p[0] + 5, p[1] + 6).fill('#b0b0b0').opacity(0.6);
    var c = gNode.circle(2 * R).center(p[0], p[1])
