    var t = serifText(gLabel, n, 46, true).fill('#000');
    t.center(p[0], p[1] - 2);
    c.on('mousemove', function (ev) { showTooltip('vertex ' + n, ev); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Vertex ' + n,
          'A spanning tree must touch every one of the nine vertices. With 9 vertices, exactly 9 \u2212 1 = 8 edges are needed: fewer leaves a vertex unreached, more would create a cycle.');
      });
  });

  // ── render ────────────────────────────────────────────────────────────
  function render() {
    var added = treeSet().slice(0, buildCount);
    var total = 0;
    EDGES.forEach(function (e) {
      var g = gfx[e.id];
      var on = added.indexOf(e.id) >= 0;
      if (on) total += e.w;
      g.band.opacity(on ? 1 : 0);
      g.ruleA.opacity(on ? 1 : 0);
      g.ruleB.opacity(on ? 1 : 0);
      g.line.opacity(on ? 0 : 1);
