      var sel = (selected === e.id);
      g.hl.opacity(sel ? 1 : 0);
      g.lbl.fill(sel ? ACCENT : '#000');
    });

    var reached = {};
    added.forEach(function (id) { reached[byId[id].u] = 1; reached[byId[id].v] = 1; });
    var showRings = (buildCount > 0 && buildCount < 8);
    NODES.forEach(function (n) { rings[n].opacity(showRings && reached[n] ? 1 : 0); });

    var tw = document.getElementById('treeWeight');
    if (tw) tw.innerHTML = 'Tree weight: ' + total + ' &nbsp;(' + buildCount + ' of 8 edges)';

    var bs = document.getElementById('buildStatus');
    if (bs) {
      bs.textContent = buildCount === 8
        ? 'Spanning: all 9 vertices reached, no cycle.'
        : (buildCount === 0
          ? 'No edges chosen yet \u2014 all 14 candidates shown.'
          : 'Partial forest: ' + buildCount + ' edge' + (buildCount === 1 ? '' : 's') + ' added so far.');
    }
    var bt = document.getElementById('buildTreeInput');
    if (bt) bt.disabled = (buildCount === 8);

    var si = document.getElementById('selInfo');
    if (si) {
      if (selected) {
        var e2 = byId[selected];
        var inT = treeSet().indexOf(selected) >= 0;
        si.textContent = 'Selected ' + e2.u + '\u2013' + e2.v + ', weight ' + e2.w + ' \u2014 ' +
          (inT ? 'part of this minimum spanning tree.' : 'excluded: it would close a cycle of no-heavier edges.');
      } else {
        si.textContent = 'Click any edge in the figure to inspect its weight and status.';
      }
    }
  }

  // ── controls ──────────────────────────────────────────────────────────
  window.toggle_treeVariant = function (on) {
    variant = on ? 'B' : 'A';
    render();
  };
  window.trigger_buildTree = function () {
    if (buildCount < 8) { buildCount++; render(); }
  };
  window.trigger_resetBuild = function () {
    buildCount = 0; selected = null; render();
  };

  // ── demo steps ────────────────────────────────────────────────────────
  var STEPS = [
    { title: 'The wiring problem', narration: 'Nine pins must be connected; every possible interconnection is an edge and its weight is the length of wire it would need. All fourteen candidate connections are shown, none chosen yet.', count: 0, variant: 'A', sel: null },
    { title: 'Cheapest links first', narration: 'Adding edges one at a time, the light connections h\u2013g (1), g\u2013f (2) and c\u2013i (2) appear. Watch the orange reached-vertex rings spread outward \u2014 the set stays acyclic the whole time.', count: 3, variant: 'A', sel: null },
    { title: 'Spanning every vertex', narration: 'By the eighth edge all nine vertices are reached with exactly 8 = 9 \u2212 1 edges and no cycle. The running total is 37 \u2014 the minimum possible wire length.', count: 8, variant: 'A', sel: null },
    { title: 'Compare the edges left out', narration: 'Click the heavy unbanded edges such as d\u2013f (14, highlighted) and b\u2013h (11): each would close a cycle and cost more than an edge already in the tree, so it is excluded.', count: 8, variant: 'A', sel: 'd-f' },
    { title: 'A minimum spanning tree is not unique', narration: 'Swap b\u2013c (8) for a\u2013h (8): the gray band shifts, the tree still spans all nine vertices with no cycle, and the total weight is still 37.', count: 8, variant: 'B', sel: null }
  ];
  var stepIndex = 2; // default view == the original figure (full Tree A)

  function applyStep(i) {
    stepIndex = Math.max(0, Math.min(STEPS.length - 1, i));
    var s = STEPS[stepIndex];
    buildCount = s.count;
    variant = s.variant;
    selected = s.sel;
    var cb = document.getElementById('treeVariantInput');
    if (cb) cb.checked = (variant === 'B');
    var n = document.getElementById('demoNarration');
    if (n) n.innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
    var l = document.getElementById('stepLabel');
    if (l) l.textContent = 'Step ' + (stepIndex + 1) + ' / ' + STEPS.length;
    render();
  }
  window.nextStep = function () { applyStep(stepIndex + 1); };
  window.prevStep = function () { applyStep(stepIndex - 1); };

  applyStep(2);
  window.__markRendered();
})();
// @FIGURE_CODE_END

